      "topic": {
        "text": "Logical AND operator",
        "refs": ["Q0000", "Q0001", "Q0002"]
      },
      "explanation_text": {
        "text": "The && operator returns true only if both operands are true. Java evaluates the expression from left to right and stops evaluating as soon as it determines the result (short‑circuit). If the first condition is false, the second condition is not evaluated.",
        "refs": ["Q0000", "Q0001", "Q0002"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "Logical OR operator",
        "refs": ["Q0002", "Q0003", "Q0004"]
      },
      "explanation_text": {
        "text": "The || operator returns true if at least one operand is true. Java evaluates from left to right and stops as soon as a true operand is found (short‑circuit). If the first operand is true, the second is not evaluated.",
        "refs": ["Q0002", "Q0003", "Q0004"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "Logical NOT operator",
        "refs": ["Q0005"]
      },
      "explanation_text": {
        "text": "The ! operator reverses the boolean value of its operand; true becomes false and false becomes true.",
        "refs": ["Q0005"]
      },
      "explanation_type": null
    }
  ],
  "examples": [
    {
      "exemplifies": {
        "text": "Temperature range check using &&",
        "refs": ["Q0000", "Q0001"]
      },
      "example_text": {
        "text": "int temperature = 22; boolean isWarm = temperature > 20 && temperature < 30; // isWarm is true",
        "refs": ["Q0000", "Q0001"]
      },
      "example_type": null
    },
    {
      "exemplifies": {
        "text": "Loan eligibility using ||",
        "refs": ["Q0003", "Q0004"]
      },
      "example_text": {
        "text": "boolean hasHighIncome = true; boolean hasGoodCredit = true; boolean isEligible = hasHighIncome || hasGoodCredit; // isEligible is true",
        "refs": ["Q0003", "Q0004"]
      },
      "example_type": null
    }
  ],
  "facts": [
    {
      "fact_text": {
        "text": "&& returns true only when both conditions are true; otherwise false.",
        "refs": ["Q0000", "Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "|| returns true when at least one condition is true; otherwise false.",
        "refs": ["Q0003", "Q0004"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Java uses short‑circuit evaluation for both && and || operators.",
        "refs": ["Q0001", "Q0004"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "! reverses a boolean value.",
        "refs": ["Q0005"]
      },
      "fact_type": null
    }
  ],
